onMount.body:
if (window.__docsEnhance) { return; }
window.__docsEnhance = true;
const ICON = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M11 9h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2h-8a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2zM5 15V5a2 2 0 0 1 2-2h10"></path></svg>';
document.querySelectorAll('pre > code').forEach((code) => {
  const pre = code.parentElement;
  if (!pre || pre.querySelector('.copy-btn')) { return; }
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'copy-btn';
  btn.setAttribute('aria-label', 'Copy code to clipboard');
  btn.innerHTML = ICON + '<span>Copy</span>';
  const label = btn.querySelector('span');
  btn.addEventListener('click', async () => {
    let ok = true;
    try { await navigator.clipboard.writeText(code.textContent || ''); } catch (e) { ok = false; }
    label.textContent = ok ? 'Copied' : 'Press Ctrl+C';
    btn.setAttribute('aria-label', ok ? 'Code copied to clipboard' : 'Copy failed, select the code and press Ctrl+C');
    if (ok) { btn.setAttribute('data-state', 'copied'); }
    setTimeout(() => {
      label.textContent = 'Copy';
      btn.setAttribute('aria-label', 'Copy code to clipboard');
      btn.removeAttribute('data-state');
    }, 2000);
  });
  pre.appendChild(btn);
});
document.querySelectorAll('docs-prose h2[id], docs-prose h3[id], docs-prose h4[id]').forEach((h) => {
  if (h.querySelector('.anchor')) { return; }
  const a = document.createElement('a');
  a.className = 'anchor';
  a.href = '#' + h.id;
  a.setAttribute('aria-label', 'Link to this section: ' + h.textContent);
  a.textContent = '#';
  h.appendChild(a);
});
const scrollers = document.querySelectorAll('main pre > code, main table');
const markScrollable = () => {
  scrollers.forEach((el) => {
    if (el.scrollWidth > el.clientWidth + 1) { el.setAttribute('tabindex', '0'); } else { el.removeAttribute('tabindex'); }
  });
};
markScrollable();
if (document.fonts && document.fonts.ready) { document.fonts.ready.then(markScrollable); }
let resizeTimer = 0;
window.addEventListener('resize', () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(markScrollable, 150); });
const links = Array.from(document.querySelectorAll('docs-toc li a[href^="#"]'));
const idOf = (a) => { try { return decodeURIComponent(a.getAttribute('href').slice(1)); } catch (e) { return ''; } };
const heads = [];
links.forEach((a) => { const h = document.getElementById(idOf(a)); if (h && heads.indexOf(h) === -1) { heads.push(h); } });
heads.sort((x, y) => (x.compareDocumentPosition(y) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1));
if (heads.length) {
  let current = '';
  const mark = (id) => {
    if (id === current) { return; }
    current = id;
    links.forEach((a) => { if (idOf(a) === id) { a.setAttribute('aria-current', 'location'); } else { a.removeAttribute('aria-current'); } });
  };
  const header = document.querySelector('docs-header');
  let queued = false;
  const update = () => {
    queued = false;
    const line = (header ? header.offsetHeight : 60) + 40;
    let id = heads[0].id;
    for (const h of heads) { if (h.getBoundingClientRect().top <= line) { id = h.id; } else { break; } }
    if (window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2) { id = heads[heads.length - 1].id; }
    mark(id);
  };
  const queue = () => { if (!queued) { queued = true; requestAnimationFrame(update); } };
  window.addEventListener('scroll', queue, { passive: true });
  window.addEventListener('resize', queue);
  update();
}
const drawer = document.getElementById('docs-drawer');
if (drawer) {
  const openers = Array.from(document.querySelectorAll('[popovertarget="docs-drawer"]')).filter((b) => b.getAttribute('popovertargetaction') !== 'hide');
  // Everything outside the drawer is made inert while it is open, so keyboard focus and screen reader
  // browsing stay in it like in a dialog; the popover itself stays declarative (Escape and a click
  // outside close it).
  const others = () => {
    const found = [];
    let node = drawer;
    while (node.parentElement && node !== document.body) {
      Array.from(node.parentElement.children).forEach((sib) => {
        if (sib !== node && !/^(SCRIPT|STYLE|TEMPLATE)$/.test(sib.tagName)) { found.push(sib); }
      });
      node = node.parentElement;
    }
    return found;
  };
  const setInert = (on) => {
    others().forEach((el) => {
      if (on) { if (!el.hasAttribute('inert')) { el.setAttribute('inert', ''); el.setAttribute('data-drawer-inert', ''); } }
      else if (el.hasAttribute('data-drawer-inert')) { el.removeAttribute('inert'); el.removeAttribute('data-drawer-inert'); }
    });
  };
  drawer.addEventListener('beforetoggle', (e) => { if (e.newState === 'closed') { setInert(false); } });
  // The drawer only exists below 960px: widening the window while it is open must not leave the page inert.
  window.matchMedia('(min-width: 961px)').addEventListener('change', (e) => { if (e.matches && drawer.matches(':popover-open')) { drawer.hidePopover(); } });
  drawer.addEventListener('toggle', (e) => {
    const open = e.newState === 'open';
    openers.forEach((b) => b.setAttribute('aria-expanded', open ? 'true' : 'false'));
    if (open) {
      drawer.setAttribute('aria-modal', 'true');
      setInert(true);
      const close = drawer.querySelector('.drawer-close');
      if (close) { close.focus(); }
    } else {
      drawer.removeAttribute('aria-modal');
      setInert(false);
      if (openers[0] && (!document.activeElement || document.activeElement === document.body)) { openers[0].focus(); }
    }
  });
}
